/**
 * Unit tests for Axis.drawLabel.
 * Since drawLabel is protected, we use a concrete subclass for testing.
 */
public class Axis_drawLabel_TriageGen0Test {

    private TestAxis axis;
    private Rectangle2D plotArea;
    private Rectangle2D dataArea;
    private AxisState state;

    @Mock
    private Graphics2D g2;
    @Mock
    private FontMetrics fm;
    @Mock
    private PlotRenderingInfo plotState;
    @Mock
    private ChartRenderingInfo chartRenderingInfo;
    @Mock
    private EntityCollection entityCollection;

    // Concrete implementation to access protected method and provide required behavior
    private static class TestAxis extends Axis {
        public TestAxis(String label) {
            super(label);
        }

        @Override
        public void configure() {}

        @Override
        public AxisSpace reserveSpace(Graphics2D g2, org.jfree.chart.plot.Plot plot, Rectangle2D plotArea, RectangleEdge edge, AxisSpace space) {
            return null;
        }

        @Override
        public AxisState draw(Graphics2D g2, double cursor, Rectangle2D plotArea, Rectangle2D dataArea, RectangleEdge edge, PlotRenderingInfo plotState) {
            return null;
        }

        @Override
        public java.util.List<Number> refreshTicks(Graphics2D g2, AxisState state, Rectangle2D dataArea, RectangleEdge edge) {
            return null;
        }

        // Expose protected method for testing
        public AxisState callDrawLabel(String label, Graphics2D g2, Rectangle2D plotArea, Rectangle2D dataArea, 
                                        RectangleEdge edge, AxisState state, PlotRenderingInfo plotState) {
            return super.drawLabel(label, g2, plotArea, dataArea, edge, state, plotState);
        }
    }

    // Mock implementation of AxisState to track cursor changes
    private static class TestAxisState extends AxisState {
        private double cursor = 100.0;
        private boolean cursorUpCalled = false;
        private boolean cursorDownCalled = false;
        private boolean cursorLeftCalled = false;
        private boolean cursorRightCalled = false;

        public void cursorUp(double val) { cursorUpCalled = true; cursor = val; }
        public void cursorDown(double val) { cursorDownCalled = true; cursor = val; }
        public void cursorLeft(double val) { cursorLeftCalled = true; cursor = val; }
        public void cursorRight(double val) { cursorRightCalled = true; cursor = val; }

        @Override public double getCursor() { return cursor; }
        @Override public void setCursor(double cursor) { this.cursor = cursor; }
    }

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        axis = new TestAxis("Test Axis");
        plotArea = new Rectangle2D.Double(0, 0, 500, 500);
        dataArea = new Rectangle2D.Double(50, 50, 400, 400);
        state = new TestAxisState();

        // Setup default mock behaviors
        when(g2.getFontMetrics()).thenReturn(fm);
        when(fm.getStringBounds(any(CharSequence.class), any(Graphics2D.class))).thenReturn(new Rectangle2D.Double(0, 0, 10, 10));

        axis.setLabelFont(new Font("SansSerif", Font.PLAIN, 12));
        axis.setLabelPaint(Color.BLACK);
        axis.setLabelInsets(new java.awt.Insets(2, 2, 2, 2));
        axis.setLabelAngle(0.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDrawLabel_NullState() {
        axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, null, plotState);
    }

    @Test
    public void testDrawLabel_NullOrEmptyLabel() {
        AxisState result1 = axis.callDrawLabel(null, g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        assertEquals(state, result1);

        AxisState result2 = axis.callDrawLabel("", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        assertEquals(state, result2);
    }

    @Test
    public void testDrawLabel_TopEdge() {
        AxisState result = axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        assertNotNull(result);
        // Verify cursor update logic (simplified verification)
        verify(g2, atLeastOnce()).setFont(any(Font.class));
    }

    @Test
    public void testDrawLabel_BottomEdge() {
        AxisState result = axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.BOTTOM, state, plotState);
        assertNotNull(result);
    }

    @Test
    public void testDrawLabel_LeftEdge() {
        AxisState result = axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.LEFT, state, plotState);
        assertNotNull(result);
    }

    @Test
    public void testDrawLabel_RightEdge() {
        AxisState result = axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.RIGHT, state, plotState);
        assertNotNull(result);
    }

    @Test
    public void testDrawLabel_WithPlotStateAndEntities() {
        // Setup complex hierarchy for entity collection
        when(plotState.getOwner()).thenReturn(chartRenderingInfo);
        when(chartRenderingInfo.getEntityCollection()).thenReturn(entityCollection);

        // We need to ensure TextUtilities doesn't crash; since we can't easily mock static TextUtilities 
        // without PowerMock, we rely on the fact that the method is called with valid objects.
        // In a real environment, TextUtilities.getTextBounds would be called.

        axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);

        // Verify that an entity was added to the collection
        verify(entityCollection, atLeastOnce()).add(any(AxisLabelEntity.class));
    }

    @Test
    public void testDrawLabel_NoPlotState() {
        // Test branch where plotState is null
        AxisState result = axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, null);
        assertNotNull(result);
    }

    @Test
    public void testDrawLabel_NoEntities() {
        // Test branch where entities is null
        when(plotState.getOwner()).thenReturn(chartRenderingInfo);
        when(chartRenderingInfo.getEntityCollection()).thenReturn(null);

        axis.callDrawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        // No exception should be thrown
    }
}
